                        "dashboard": "cs_web",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_sub_cs_manufacturing": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/sub_cs_manufacturing.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_manufacturing",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_sub_cs_sap": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/sub_cs_sap_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_01": {
            "type": "coolashaker_studio.service_flow",
            "dataSources": {
                "primary": "ds_chain"
            },
            "options": {
                "orientation": "horizontal"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_resp"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "ms",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1000,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1000,
                        "to": 2000,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 2000,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_db"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "ms",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 400,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 400,
                        "to": 800,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 800,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_users"
            },
            "options": {
                "majorColor": "#eaf2ff",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_wp"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 85,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_hana_mem"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 80,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 80,
                        "to": 90,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 90,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_hana_cpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 85,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_08": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_upd"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
